import * as React from 'react';
import { Icon } from '@/components/ui/icon';
import { IconShell } from '@/components/ui/icon-shell';
import {
  type TabSize,
  Tabs,
  TabsContent,
  TabsList,
  TabsTrigger,
} from '@/components/ui/tabs';

function TabsSizeExample({
  size,
  iconSize,
}: {
  size?: TabSize;
  iconSize: 'sm' | 'default';
}) {
  const [value, setValue] = React.useState('account');
  return (
    <Tabs
      value={value}
      onValueChange={setValue}
      className="w-[400px]"
      size={size}
      hideBaseline>
      <TabsList>
        <TabsTrigger value="account">
          <IconShell
            size={iconSize}
            variant={value === 'account' ? 'primary' : 'secondary'}>
            <Icon icon="crop_free" />
          </IconShell>
          Account
        </TabsTrigger>
        <TabsTrigger value="password">
          <IconShell
            size={iconSize}
            variant={value === 'password' ? 'primary' : 'secondary'}>
            <Icon icon="crop_free" />
          </IconShell>
          Password
        </TabsTrigger>
      </TabsList>
      <TabsContent value="account">
        {size === 'lg'
          ? 'Large tabs content.'
          : size === 'xl'
            ? 'Extra large tabs content.'
            : 'Default tabs content.'}
      </TabsContent>
      <TabsContent value="password">Password content.</TabsContent>
    </Tabs>
  );
}

export function TabsSizes() {
  return (
    <div className="flex flex-col gap-8">
      <TabsSizeExample iconSize="sm" />
      <TabsSizeExample size="lg" iconSize="default" />
      <TabsSizeExample size="xl" iconSize="default" />
    </div>
  );
}

